-- [S2] FRS program links for the 18 registry IDs: which other EPA / federal systems each plant sits in
SELECT TO_VARCHAR(REGISTRY_ID) AS REG, PGM_SYS_ACRNM, COUNT(*) AS N, LISTAGG(DISTINCT PGM_SYS_ID, ';') WITHIN GROUP (ORDER BY PGM_SYS_ID) AS IDS, ANY_VALUE(PRIMARY_NAME) AS NM, ANY_VALUE(CITY_NAME) AS CITY, ANY_VALUE(FIPS_CODE) AS FIPS
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_FRS_FRS_PROGRAM_LINKS
WHERE TO_VARCHAR(REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602')
GROUP BY 1,2 ORDER BY 1,2
